import{_t as e,it as t,n,rt as r}from"./chunks/framework.BmT8T0yb.js";var i=JSON.parse(`{"title":"Return & Land (PX4)","description":"","frontmatter":{"qt_version":"6.12.0"},"headers":[],"relativePath":"en/qgc-user-guide/setup_view/px4/return_land.md","filePath":"en/qgc-user-guide/setup_view/px4/return_land.md"}`),a={name:`en/qgc-user-guide/setup_view/px4/return_land.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="return-land-px4" tabindex="-1">Return &amp; Land (PX4) <a class="header-anchor" href="#return-land-px4" aria-label="Permalink to “Return &amp; Land (PX4)”">​</a></h1><p>The Return &amp; Land page configures how the vehicle returns, what it does when it arrives, and how it lands. Every <em>Return</em> action uses these settings, including the failsafes on the <a href="./failsafes.html">Failsafes</a> page and the Return flight mode. It is designed for PX4 1.17 or later. Older firmware shows only the settings it has.</p><p>The page only shows settings the connected vehicle has, and only those that apply to its type. The choices, units and limits of each setting come from the vehicle&#39;s parameter metadata. Changes are written to the vehicle immediately and can be made in flight.</p><h2 id="return" tabindex="-1">Return <a class="header-anchor" href="#return" aria-label="Permalink to “Return”">​</a></h2><ul><li><strong>Route</strong> — where the vehicle goes and how high it flies: the destination, the altitude it climbs to, and the altitude cone and approach settings.</li><li><strong>Arrival</strong> — what the vehicle does once it reaches the destination: the loiter altitude, how long it loiters before landing (<em>-1</em> loiters and does not land), and the loiter radius for fixed wings and VTOLs.</li></ul><h2 id="landing" tabindex="-1">Landing <a class="header-anchor" href="#landing" aria-label="Permalink to “Landing”">​</a></h2><ul><li><strong>Descent</strong> — how fast the vehicle descends close to the ground, for multicopters and VTOLs. <em>Slow descent below</em> must be higher than <em>Landing speed below</em>. The <em>Landing descent rate</em> is set by PX4 itself while the overall vertical velocity limit on the Flight Behavior page is on, so it can&#39;t be edited then.</li><li><strong>Touchdown</strong> — precision landing, and how long after landing the vehicle disarms (<em>0</em> or negative disables).</li></ul>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};